import numpy as np
def perceptron(X, y, eta=0.1, epochs=20):
    w = np.zeros(X.shape[1]); b = 0.0
    for _ in range(epochs):
        for xi, yi in zip(X, y):
            pred = 1 if (w @ xi + b) > 0 else 0
            w += eta * (yi - pred) * xi
            b += eta * (yi - pred)
    return w, b

